contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function testSeedThenCollect(uint256 drugs) public {
        require(!c.initialized());
        require(c.marketDrugs() == 0);

        c.seedMarket(drugs); if (__ESBMC_reverted()) return;

        bool reverted;
        c.collectDrugs(address(0)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted);
    }
}

