pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel as C} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _testSeedThenCollect(uint256 drugs) internal {
        vm.assume(!c.initialized());
        vm.assume(c.marketDrugs() == 0);
        try c.seedMarket(drugs) {} catch { return; }
        bool reverted;
        try c.collectDrugs(address(0)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }

    function testFuzz_testSeedThenCollect(uint256 drugs) public {
        _testSeedThenCollect(drugs);
    }

    receive() external payable {}
}

